#!/usr/bin/env bash
# Run the three arms (one seed) in parallel with shared settings plus extra evolve arguments.
#   tmux new-session -d -s wingbeat_v2 "bash experiments/algorithms/wingbeat_snn/run_arms.sh <scratch> <out> <seed> [extra evolve args]"
# Extra arguments are appended, so they override the defaults below (argparse keeps the last value).
# Do not edit this file while a launched copy is still running: bash reads scripts incrementally.
set -u
SCRATCH="$1"
OUT="$2"
SEED="$3"
shift 3
PYTHON="${PYTHON:-/home/robot/miniconda3/envs/mujoco/bin/python}"
cd "$(dirname "$0")/../../.."
mkdir -p "$OUT"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
for m in snn_neat_delay ann_neat snn_fixed; do
  "$PYTHON" -W ignore -m experiments.algorithms.wingbeat_snn.evolve --method "$m" --seed "$SEED" --scratch "$SCRATCH" \
    --output "$OUT/${m}_seed${SEED}" --population 20 --generations 15 --cases 4 --seconds 7 \
    --validation-cases 8 --validate-every 5 --workers 6 "$@" > "$OUT/${m}_seed${SEED}.log" 2>&1 &
done
wait
ok=1
for m in snn_neat_delay ann_neat snn_fixed; do [ -s "$OUT/${m}_seed${SEED}/results.json" ] || ok=0; done
[ $ok = 1 ] && echo "finished $(date -Is)" > "$OUT/DONE_seed${SEED}"
